import math


def letter_probabilities(scores):
    if not scores:
        raise ValueError('scores must not be empty')
    top = max(scores.values())
    weights = {letter: math.exp(value - top) for letter, value in scores.items()}
    total = sum(weights.values())
    return {letter: weight / total for letter, weight in weights.items()}


def choose_option(scores):
    probabilities = letter_probabilities(scores)
    best = min(probabilities, key=lambda letter: (-probabilities[letter], letter))
    return best, probabilities[best]
